CREATE TABLE rule_linguistics_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id),skill_rule_id bigint NOT NULL UNIQUE REFERENCES rule_skill(rule_id),additional_languages_per_level smallint NOT NULL CHECK(additional_languages_per_level=1),native_language_requires_skill boolean NOT NULL CHECK(NOT native_language_requires_skill),level_zero_grants_simple_phrases boolean NOT NULL CHECK(level_zero_grants_simple_phrases),decipher_preserved_language_allowed boolean NOT NULL CHECK(decipher_preserved_language_allowed));
COMMENT ON TABLE rule_linguistics_mechanic IS 'CE-SKILL-010 paired-source native, additional-language, phrase, and decipher mechanics.';
